float map(vec3 p) {
  p.z += time * 2.5;
  vec2 t = abs(p.xy) - vec2(1.5, 1.1);
  float tunnel = -max(t.x, t.y);
  float ribs = abs(mod(p.z, 2.0) - 1.0) - 0.15;
  return min(-tunnel, ribs + 0.1);
}
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  vec3 ro = vec3(0.0, 0.0, -1.0);
  vec3 rd = normalize(vec3(p, 1.4));
  float t = 0.0;
  for (int i = 0; i < 50; i++) {
    float d = map(ro + rd * t);
    if (d < 0.003 || t > 18.0) break;
    t += d * 0.8;
  }
  vec3 col = vec3(0.01, 0.02, 0.03);
  if (t < 18.0) {
    vec3 pos = ro + rd * t;
    float lightStripe = step(0.9, cos(pos.z * 3.1415 + time * 5.0));
    float stripes = step(0.5, fract((pos.x + pos.z) * 2.0));
    vec3 surface = mix(vec3(0.1, 0.12, 0.15), vec3(0.8, 0.6, 0.1) * stripes, step(0.9, -pos.y));
    float fog = 1.0 / (1.0 + t * t * 0.03);
    col = (surface + lightStripe * vec3(0.2, 0.8, 1.0) * 2.0) * fog;
  }
  ret = col;
}
